CREATE TABLE "MarketCompany" ("organizationId" TEXT PRIMARY KEY,"voen" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"region" TEXT NOT NULL,"documents" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"reason" TEXT NOT NULL DEFAULT '',"reviewedBy" TEXT,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "MarketItem" ("id" TEXT PRIMARY KEY,"ownerId" TEXT NOT NULL,"name" TEXT NOT NULL,"category" TEXT NOT NULL,"brand" TEXT NOT NULL,"model" TEXT NOT NULL,"manufacturer" TEXT NOT NULL,"origin" TEXT NOT NULL,"unit" TEXT NOT NULL,"attributes" JSONB NOT NULL,"documents" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"reason" TEXT NOT NULL DEFAULT '',"reviewedBy" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "MarketItem_status_category_idx" ON "MarketItem"("status","category");
CREATE TABLE "MarketListing" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"itemId" TEXT NOT NULL,"region" TEXT NOT NULL,"availability" TEXT NOT NULL,"quantity" DECIMAL(14,3),"leadDays" INTEGER,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "MarketListing_organizationId_itemId_key" ON "MarketListing"("organizationId","itemId");
CREATE TABLE "MarketCase" ("id" TEXT PRIMARY KEY,"kind" TEXT NOT NULL,"buyerId" TEXT NOT NULL,"supplierId" TEXT,"selectedBidId" TEXT UNIQUE,"status" TEXT NOT NULL,"category" TEXT NOT NULL,"region" TEXT NOT NULL,"visibility" TEXT NOT NULL,"invited" JSONB NOT NULL,"data" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "MarketCase_buyerId_kind_idx" ON "MarketCase"("buyerId","kind");
CREATE INDEX "MarketCase_supplierId_kind_idx" ON "MarketCase"("supplierId","kind");
CREATE INDEX "MarketCase_kind_status_category_region_idx" ON "MarketCase"("kind","status","category","region");
CREATE TABLE "MarketBid" ("id" TEXT PRIMARY KEY,"rfqId" TEXT NOT NULL,"supplierId" TEXT NOT NULL,"revision" INTEGER NOT NULL,"data" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "MarketBid_rfqId_supplierId_revision_key" ON "MarketBid"("rfqId","supplierId","revision");
CREATE TABLE "MarketTariff" ("id" TEXT PRIMARY KEY,"side" TEXT NOT NULL,"scope" TEXT NOT NULL,"target" TEXT NOT NULL,"rate" DECIMAL(8,4) NOT NULL,"basis" TEXT NOT NULL,"effectiveFrom" TEXT NOT NULL,"effectiveTo" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "MarketTariff_side_scope_target_idx" ON "MarketTariff"("side","scope","target");
CREATE TABLE "MarketPolicy" ("id" TEXT PRIMARY KEY DEFAULT 'default',"dueDays" INTEGER NOT NULL DEFAULT 7,"warnDays" INTEGER NOT NULL DEFAULT 15,"restrictDays" INTEGER NOT NULL DEFAULT 30,"requiredProofCategories" JSONB NOT NULL DEFAULT '[]');
CREATE TABLE "MarketCharge" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL,"receiptId" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"side" TEXT NOT NULL,"acceptedAt" TEXT NOT NULL,"dueAt" TEXT NOT NULL,"base" DECIMAL(14,2) NOT NULL,"rate" DECIMAL(8,4) NOT NULL,"amount" DECIMAL(14,2) NOT NULL,"paid" DECIMAL(14,2) NOT NULL DEFAULT 0,"credit" DECIMAL(14,2) NOT NULL DEFAULT 0,"tariff" JSONB NOT NULL);
CREATE UNIQUE INDEX "MarketCharge_receiptId_side_key" ON "MarketCharge"("receiptId","side");
CREATE INDEX "MarketCharge_organizationId_dueAt_idx" ON "MarketCharge"("organizationId","dueAt");
CREATE TABLE "MarketPayment" ("id" TEXT PRIMARY KEY,"chargeId" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"amount" DECIMAL(14,2) NOT NULL,"proof" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"reviewedBy" TEXT,"reviewedAt" TIMESTAMP(3),"note" TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "MarketPayment_organizationId_status_idx" ON "MarketPayment"("organizationId","status");
CREATE TABLE "MarketAcceptanceGrant" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"accountId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"locationId" TEXT NOT NULL,"limit" DECIMAL(14,2) NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE UNIQUE INDEX "MarketAcceptanceGrant_organizationId_accountId_projectId_locationId_key" ON "MarketAcceptanceGrant"("organizationId","accountId","projectId","locationId");
CREATE TABLE "MarketEvent" ("id" TEXT PRIMARY KEY,"caseId" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"accountId" TEXT NOT NULL,"kind" TEXT NOT NULL,"data" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "MarketEvent_caseId_createdAt_idx" ON "MarketEvent"("caseId","createdAt");
CREATE TABLE "MarketMessage" ("id" TEXT PRIMARY KEY,"caseId" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"accountId" TEXT NOT NULL,"text" TEXT NOT NULL,"attachments" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "MarketMessage_caseId_createdAt_idx" ON "MarketMessage"("caseId","createdAt");
ALTER TABLE "MarketMessage" ADD COLUMN "recipientId" TEXT;
CREATE TABLE "MessageOutbox" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"channel" TEXT NOT NULL,"kind" TEXT NOT NULL,"reference" TEXT NOT NULL,"payload" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'awaiting_provider',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "MessageOutbox_organizationId_channel_kind_reference_key" ON "MessageOutbox"("organizationId","channel","kind","reference");
